#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
PROYECTO MATEMÁTICAS DISCRETAS – VERSIÓN BETA (ENTREGA 1 / AVANCE PRELIMINAR)
Universidad del Norte – Departamento de Matemáticas y Estadísticas
=============================================================================
Modelado preliminar de la red de escorrentía interna del Campus Uninorte
utilizando los conceptos fundamentales de la Unidad 3 (Secciones 3.1 a 3.3)
y las clases de Teoría de Grafos (Prof. Yesneri Zuleta & MSc Iván Gómez):

  1. Definición formal de grafo G = (V, A) y clasificación:
     - Simple vs. Multigrafo / Pseudografo
     - Dirigido (digrafo) vs. No dirigido (grafo subyacente)
  2. Vecindades de un vértice:
     - Vecindad abierta N_G(v) y vecindad cerrada N_G[v] = N_G(v) ∪ {v}
     - Vecindad de entrada N_G⁻(v) y vecindad de salida N_G⁺(v)
  3. Grado o valencia de un vértice y valores extremos:
     - grad(v), grad⁻(v), grad⁺(v)
     - Grado mínimo δ(G) y grado máximo Δ(G)
     - Extremos en digrafos: δ⁻(G), Δ⁻(G), δ⁺(G), Δ⁺(G)
     - Teorema del Apretón de Manos (TAM): ∑ grad(v) = 2m  y  ∑ grad⁻(v) = ∑ grad⁺(v) = m
     - Corolario: número par de vértices con grado impar
  4. Representaciones de grafos:
     - Lista de adyacencia
     - Matriz de adyacencia A (n × n)
     - Matriz de incidencia M (n × m)

Ejecutar:
    python arroyos_beta_uninorte.py
"""

from __future__ import annotations

import math
import os
import tkinter as tk
from tkinter import ttk
from typing import Dict, List, Optional, Set, Tuple


# ============================================================================
# 1. ESTRUCTURA DEL GRAFO (UNIDAD 3.1 - 3.3)
# ============================================================================
class NodoCampus:
    """Representa un vértice v ∈ V dentro del campus de la Universidad del Norte."""

    def __init__(self, id_: str, nombre: str, ubicacion: str) -> None:
        self.id = id_
        self.nombre = nombre
        self.ubicacion = ubicacion
        self.reportes: int = 0
        self.estado: str = "VERDE"  # VERDE (Normal), AMARILLO (Preventivo), NARANJA (Reporte), ROJO (Crítico)


class GrafoDrenajeBeta:
    """
    Grafo dirigido simple G = (V, A) que modela el sentido del drenaje pluvial
    interno del campus de Uninorte (desde la Cra 51B hacia los colectores de la Cra 53).
    """

    def __init__(self) -> None:
        self.nodos: Dict[str, NodoCampus] = {}
        self.arcos: List[Tuple[str, str]] = []

    def agregar_nodo(self, id_: str, nombre: str, ubicacion: str) -> None:
        self.nodos[id_] = NodoCampus(id_, nombre, ubicacion)

    def agregar_arco(self, u: str, v: str) -> None:
        if (u, v) not in self.arcos:
            self.arcos.append((u, v))

    @property
    def vertices(self) -> List[str]:
        return list(self.nodos.keys())

    # -- Vecindades (Prof. Yesneri Zuleta, diap. 5-6) ------------------------
    def vecindad_entrada(self, v: str) -> List[str]:
        """N_G⁻(v) = {u ∈ V | (u, v) ∈ A}."""
        return [u for u, w in self.arcos if w == v]

    def vecindad_salida(self, v: str) -> List[str]:
        """N_G⁺(v) = {u ∈ V | (v, u) ∈ A}."""
        return [w for u, w in self.arcos if u == v]

    def vecindad_abierta(self, v: str) -> List[str]:
        """N_G(v) = {u ∈ V | {u, v} ∈ E} en el grafo no dirigido subyacente."""
        vecinos = set(self.vecindad_entrada(v)) | set(self.vecindad_salida(v))
        return [u for u in self.vertices if u in vecinos]

    def vecindad_cerrada(self, v: str) -> List[str]:
        """N_G[v] = N_G(v) ∪ {v}."""
        vecinos = set(self.vecindad_abierta(v)) | {v}
        return [u for u in self.vertices if u in vecinos]

    # -- Grados o valencias (Prof. Yesneri Zuleta, diap. 7-9) ----------------
    def grad_entrada(self, v: str) -> int:
        """grad⁻(v) = |N_G⁻(v)|."""
        return len(self.vecindad_entrada(v))

    def grad_salida(self, v: str) -> int:
        """grad⁺(v) = |N_G⁺(v)|."""
        return len(self.vecindad_salida(v))

    def grad(self, v: str) -> int:
        """grad(v) = |N_G(v)| en el grafo simple subyacente."""
        return len(self.vecindad_abierta(v))

    # -- Representaciones (Unidad 3.3, diap. 13-15) --------------------------
    def matriz_adyacencia(self, dirigido: bool = True) -> List[List[int]]:
        vs = self.vertices
        idx = {v: i for i, v in enumerate(vs)}
        n = len(vs)
        mat = [[0] * n for _ in range(n)]
        for u, v in self.arcos:
            mat[idx[u]][idx[v]] = 1
            if not dirigido:
                mat[idx[v]][idx[u]] = 1
        return mat

    def matriz_incidencia_no_dirigida(self) -> List[List[int]]:
        """M_ie = 1 si el vértice i es extremo de la arista e, 0 en otro caso."""
        vs = self.vertices
        idx = {v: i for i, v in enumerate(vs)}
        mat = [[0] * len(self.arcos) for _ in range(len(vs))]
        for j, (u, v) in enumerate(self.arcos):
            mat[idx[u]][j] = 1
            mat[idx[v]][j] = 1
        return mat


def construir_red_campus_beta() -> GrafoDrenajeBeta:
    """
    Construye el modelo preliminar de 9 nodos sobre el mapa interno de Uninorte.
    """
    g = GrafoDrenajeBeta()
    nodos_definicion = [
        ("N1", "Circunvalar / Cra 51B", "Intercambiador sur Cra 51B / Villa Julia"),
        ("N2", "Cra 53 / PriceSmart", "Acceso oriental sobre Carrera 53"),
        ("N3", "Depresión Portoazul", "Corredor Universitario Cra 51B"),
        ("N4", "Frente Uninorte (Puerta 1)", "Acceso principal campus Uninorte"),
        ("N5", "Drenaje Campus Uninorte", "Red interna de escorrentía campus"),
        ("N6", "Villa Campestre", "Cruce canal pluvial Villa Campestre"),
        ("N7", "Eduardo Santos", "Confluencia canal perimetral Eduardo Santos"),
        ("N8", "Arroyo León (Vía La Playa)", "Cauce principal troncal Arroyo León"),
        ("N9", "Ciénaga de Mallorquín", "Desembocadura y sumidero natural final"),
    ]
    for id_, nom, ubi in nodos_definicion:
        g.agregar_nodo(id_, nom, ubi)

    # Arcos dirigidos siguiendo la pendiente sur -> norte (Cra 51B -> Cra 53)
    arcos = [
        ("N1", "N3"),
        ("N2", "N4"),
        ("N3", "N5"),
        ("N4", "N5"),
        ("N4", "N6"),
        ("N5", "N7"),
        ("N5", "N8"),
        ("N6", "N7"),
        ("N7", "N9"),
        ("N8", "N9"),
    ]
    for u, v in arcos:
        g.agregar_arco(u, v)
    return g


# ============================================================================
# 2. INTERFAZ GRÁFICA BETA (SENCILLA PARA ENTREGA 1)
# ============================================================================
COLORES_BETA = {
    "VERDE": "#2e9e4f",
    "AMARILLO": "#f1c40f",
    "NARANJA": "#f28c28",
    "ROJO": "#d62828",
}


class AppBeta(tk.Tk):
    """Ventana prototipo de la Entrega 1."""

    MAPA_W, MAPA_H = 768, 395
    RADIO = 13

    # Posiciones (x, y) calibradas con precisión sobre el mapa del corredor Uninorte (768 × 395)
    # Recorrido de drenaje pluvial desde Uninorte/Cra 51B/Cra 53 hacia Arroyo León y Ciénaga de Mallorquín
    POS: Dict[str, Tuple[int, int]] = {
        "N1": (398, 371),  # Entrada Circunvalar / 90A (Villa Julia)
        "N2": (615, 341),  # Rotonda Cra 53 / PriceSmart
        "N3": (383, 334),  # Depresión Portoazul / Corredor Univ.
        "N4": (469, 341),  # Frente Uninorte / Cra 51B (Puerta 1)
        "N5": (428, 296),  # Drenaje Interno Campus Uninorte
        "N6": (345, 274),  # Box-culvert Villa Campestre
        "N7": (293, 214),  # Colector Eduardo Santos
        "N8": (356, 184),  # Arroyo León (Vía La Playa)
        "N9": (413, 83),   # Ciénaga de Mallorquín (sumidero final)
    }

    def __init__(self) -> None:
        super().__init__()
        self.title("Entrega 1 (Versión Beta) – Sistema de Alerta de Arroyos Uninorte")
        self.geometry("1260x670")
        self.minsize(1180, 630)

        self.grafo = construir_red_campus_beta()
        self.seleccion = "N5"
        self.umbral_k = 3

        self.img_mapa: Optional[tk.PhotoImage] = None
        self._cargar_mapa()

        self._construir_interfaz()
        self._mostrar_resumen_unidad3()
        self._dibujar_mapa()

    def _cargar_mapa(self) -> None:
        ruta_png = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mapa_campus_uninorte.png")
        try:
            if os.path.exists(ruta_png):
                self.img_mapa = tk.PhotoImage(file=ruta_png)
            elif MAPA_CAMPUS_B64.strip():
                self.img_mapa = tk.PhotoImage(data="".join(MAPA_CAMPUS_B64.split()))
        except tk.TclError:
            self.img_mapa = None

    def _construir_interfaz(self) -> None:
        self.columnconfigure(0, weight=0)
        self.columnconfigure(1, weight=1)
        self.rowconfigure(0, weight=1)

        # Lienzo izquierdo con el mapa del campus
        marco_izq = ttk.LabelFrame(self, text="Cercanías Uninorte – Corredor de Escorrentía hacia Ciénaga de Mallorquín")
        marco_izq.grid(row=0, column=0, sticky="ns", padx=8, pady=8)

        self.canvas = tk.Canvas(
            marco_izq,
            width=self.MAPA_W,
            height=self.MAPA_H,
            bg="#eef2f6",
            highlightthickness=1,
            highlightbackground="#94a3b8",
        )
        self.canvas.pack(padx=4, pady=(4, 2))

        # Leyenda de estados de alerta y sentido de escorrentía
        marco_leyenda = ttk.Frame(marco_izq)
        marco_leyenda.pack(fill="x", padx=6, pady=(0, 4))
        ttk.Label(marco_leyenda, text="● Verde: Normal", foreground="#2e9e4f", font=("Segoe UI", 8, "bold")).pack(side="left", padx=4)
        ttk.Label(marco_leyenda, text="● Amarillo: Alerta Preventiva N⁺(v)", foreground="#d97706", font=("Segoe UI", 8, "bold")).pack(side="left", padx=4)
        ttk.Label(marco_leyenda, text="● Rojo: Arroyo Activo (k≥3)", foreground="#dc2626", font=("Segoe UI", 8, "bold")).pack(side="left", padx=4)
        ttk.Label(marco_leyenda, text="➔ Escorrentía hacia Mallorquín", foreground="#1e3a8a", font=("Segoe UI", 8, "bold")).pack(side="right", padx=4)

        # Panel derecho de controles y análisis de la Unidad 3
        marco_der = ttk.Frame(self)
        marco_der.grid(row=0, column=1, sticky="nsew", padx=(0, 8), pady=8)
        marco_der.columnconfigure(0, weight=1)
        marco_der.rowconfigure(2, weight=1)

        # 1. Controles básicos
        ctrl = ttk.LabelFrame(marco_der, text="Controles del Prototipo Beta (Entrega 1)")
        ctrl.grid(row=0, column=0, sticky="ew", pady=(0, 6))
        ctrl.columnconfigure(1, weight=1)

        ttk.Label(ctrl, text="Seleccionar vértice v ∈ V:").grid(
            row=0, column=0, sticky="w", padx=8, pady=6
        )
        opciones = [f"{k} - {n.nombre}" for k, n in self.grafo.nodos.items()]
        self.combo = ttk.Combobox(ctrl, state="readonly", values=opciones)
        self.combo.set(f"{self.seleccion} - {self.grafo.nodos[self.seleccion].nombre}")
        self.combo.grid(row=0, column=1, sticky="ew", padx=8, pady=6)
        self.combo.bind("<<ComboboxSelected>>", self._on_combo)

        botones = ttk.Frame(ctrl)
        botones.grid(row=1, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 6))
        ttk.Button(
            botones,
            text="📢 Registrar Reporte Ciudadano (+1)",
            command=self._registrar_reporte,
        ).pack(side="left", padx=(0, 6))
        ttk.Button(
            botones,
            text="🌊 Simular Arroyo en Cabecera",
            command=self._simular_arroyo_cabecera,
        ).pack(side="left", padx=(0, 6))
        ttk.Button(
            botones,
            text="🔄 Reiniciar Estados a Verde",
            command=self._reiniciar,
        ).pack(side="left", padx=(0, 6))

        # 2. Botones de vistas matemáticas (Unidad 3.1 - 3.3)
        vistas = ttk.LabelFrame(marco_der, text="Consultas de Matemáticas Discretas (Unidad 3.1 – 3.3)")
        vistas.grid(row=1, column=0, sticky="ew", pady=(0, 6))
        ttk.Button(
            vistas,
            text="1. Grados, Vecindades y TAM",
            command=self._mostrar_resumen_unidad3,
        ).pack(side="left", padx=6, pady=6)
        ttk.Button(
            vistas,
            text="2. Lista y Matriz de Adyacencia",
            command=self._mostrar_adyacencia,
        ).pack(side="left", padx=6, pady=6)
        ttk.Button(
            vistas,
            text="3. Matriz de Incidencia",
            command=self._mostrar_incidencia,
        ).pack(side="left", padx=6, pady=6)

        # 3. Área de resultados y consola
        salida_frame = ttk.LabelFrame(marco_der, text="Resultados Formales y Estado del Nodo")
        salida_frame.grid(row=2, column=0, sticky="nsew")
        salida_frame.columnconfigure(0, weight=1)
        salida_frame.rowconfigure(1, weight=1)

        self.lbl_nodo = ttk.Label(
            salida_frame,
            text="",
            font=("Consolas", 9, "bold"),
            foreground="#1e3a8a",
            justify="left",
        )
        self.lbl_nodo.grid(row=0, column=0, sticky="ew", padx=8, pady=6)

        self.txt = tk.Text(
            salida_frame,
            wrap="none",
            font=("Consolas", 9),
            bg="#fcfcfd",
            state="disabled",
        )
        sc_y = ttk.Scrollbar(salida_frame, orient="vertical", command=self.txt.yview)
        sc_x = ttk.Scrollbar(salida_frame, orient="horizontal", command=self.txt.xview)
        self.txt.configure(yscrollcommand=sc_y.set, xscrollcommand=sc_x.set)
        self.txt.grid(row=1, column=0, sticky="nsew", padx=(6, 0), pady=(0, 4))
        sc_y.grid(row=1, column=1, sticky="ns", pady=(0, 4))
        sc_x.grid(row=2, column=0, sticky="ew", padx=(6, 0))

    # -- eventos --------------------------------------------------------------
    def _on_combo(self, _e: object = None) -> None:
        val = self.combo.get().split(" - ")[0]
        if val in self.grafo.nodos:
            self.seleccion = val
            self._dibujar_mapa()

    def _seleccionar_en_mapa(self, id_: str) -> None:
        self.seleccion = id_
        self.combo.set(f"{id_} - {self.grafo.nodos[id_].nombre}")
        self._dibujar_mapa()

    def _registrar_reporte(self) -> None:
        nodo = self.grafo.nodos[self.seleccion]
        nodo.reportes += 1
        if nodo.reportes >= self.umbral_k:
            nodo.estado = "ROJO"
            # Propaga alerta preventiva a su vecindad de salida N_G⁺(v)
            for vec in self.grafo.vecindad_salida(nodo.id):
                if self.grafo.nodos[vec].estado == "VERDE":
                    self.grafo.nodos[vec].estado = "AMARILLO"
        elif nodo.estado != "ROJO":
            nodo.estado = "NARANJA"
        self._dibujar_mapa()

    def _simular_arroyo_cabecera(self) -> None:
        """Simula una emergencia de arroyo pluvial en las entradas N1 y N2 propagando alertas."""
        for n in self.grafo.nodos.values():
            n.reportes = 0
            n.estado = "VERDE"
        self.grafo.nodos["N1"].estado = "ROJO"
        self.grafo.nodos["N1"].reportes = self.umbral_k
        self.grafo.nodos["N2"].estado = "ROJO"
        self.grafo.nodos["N2"].reportes = self.umbral_k
        # Alertas preventivas aguas abajo
        for cabecera in ["N1", "N2"]:
            for vec in self.grafo.vecindad_salida(cabecera):
                if self.grafo.nodos[vec].estado == "VERDE":
                    self.grafo.nodos[vec].estado = "AMARILLO"
        self._dibujar_mapa()

    def _reiniciar(self) -> None:
        for n in self.grafo.nodos.values():
            n.reportes = 0
            n.estado = "VERDE"
        self._dibujar_mapa()

    # -- dibujo del mapa ------------------------------------------------------
    def _dibujar_mapa(self) -> None:
        c = self.canvas
        c.delete("all")
        if self.img_mapa is not None:
            c.create_image(0, 0, image=self.img_mapa, anchor="nw")
        else:
            c.create_rectangle(0, 0, self.MAPA_W, self.MAPA_H, fill="#e2e8f0", outline="")

        r = self.RADIO
        # Dibujar arcos dirigidos (u, v) ∈ A
        for u, v in self.grafo.arcos:
            x1, y1 = self.POS[u]
            x2, y2 = self.POS[v]
            d = math.hypot(x2 - x1, y2 - y1) or 1.0
            ux, uy = (x2 - x1) / d, (y2 - y1) / d
            crit = self.grafo.nodos[u].estado == "ROJO"
            c.create_line(
                x1 + ux * r,
                y1 + uy * r,
                x2 - ux * (r + 3),
                y2 - uy * (r + 3),
                arrow=tk.LAST,
                arrowshape=(10, 12, 5),
                fill="#d62828" if crit else "#1e3a8a",
                width=3.5 if crit else 2.5,
            )

        # Dibujar vértices v ∈ V
        for id_, nodo in self.grafo.nodos.items():
            x, y = self.POS[id_]
            sel = id_ == self.seleccion
            tag = f"v_{id_}"
            c.create_oval(
                x - r,
                y - r,
                x + r,
                y + r,
                fill=COLORES_BETA[nodo.estado],
                outline="#1d4ed8" if sel else "#111827",
                width=3.5 if sel else 2,
                tags=(tag,),
            )
            c.create_text(
                x,
                y,
                text=id_,
                fill="#111827" if nodo.estado == "AMARILLO" else "#ffffff",
                font=("Segoe UI", 9, "bold"),
                tags=(tag,),
            )
            # Etiqueta corta al lado del nodo (arriba si está cerca del borde inferior)
            pos_y = y - r - 3 if y > self.MAPA_H - 35 else y + r + 3
            anch = "s" if y > self.MAPA_H - 35 else "n"
            t = c.create_text(
                x,
                pos_y,
                text=nodo.nombre.split(" / ")[0],
                anchor=anch,
                font=("Segoe UI", 7, "bold" if sel else "normal"),
                fill="#0f172a",
            )
            bx0, by0, bx1, by1 = c.bbox(t)
            rect = c.create_rectangle(
                bx0 - 2, by0 - 1, bx1 + 2, by1 + 1, fill="#ffffff", outline="#cbd5e1"
            )
            c.tag_lower(rect, t)

            c.tag_bind(tag, "<Button-1>", lambda _e, i=id_: self._seleccionar_en_mapa(i))
            c.tag_bind(
                tag,
                "<Double-Button-1>",
                lambda _e, i=id_: (self._seleccionar_en_mapa(i), self._registrar_reporte()),
            )

        self._actualizar_info_nodo()

    def _actualizar_info_nodo(self) -> None:
        g = self.grafo
        v = self.seleccion
        n = g.nodos[v]
        self.lbl_nodo.configure(
            text=(
                f"Nodo seleccionado: {v} ({n.nombre})\n"
                f"Estado: {n.estado}  |  Reportes: {n.reportes}/{self.umbral_k}\n"
                f"N_G⁻({v}) = {g.vecindad_entrada(v)} (grad⁻={g.grad_entrada(v)})   |   "
                f"N_G⁺({v}) = {g.vecindad_salida(v)} (grad⁺={g.grad_salida(v)})\n"
                f"N_G({v})  = {g.vecindad_abierta(v)} (grad={g.grad(v)})   |   "
                f"N_G[{v}]  = {g.vecindad_cerrada(v)}"
            )
        )

    def _escribir_texto(self, lineas: List[str]) -> None:
        self.txt.configure(state="normal")
        self.txt.delete("1.0", "end")
        self.txt.insert("1.0", "\n".join(lineas))
        self.txt.configure(state="disabled")

    # -- Vistas de la Entrega 1 (Unidad 3.1 - 3.3) ----------------------------
    def _mostrar_resumen_unidad3(self) -> None:
        g = self.grafo
        vs = g.vertices
        n = len(vs)
        m = len(g.arcos)
        grados = [g.grad(v) for v in vs]
        g_in = [g.grad_entrada(v) for v in vs]
        g_out = [g.grad_salida(v) for v in vs]
        impares = [v for v in vs if g.grad(v) % 2 == 1]

        lineas = [
            "==========================================================================",
            "ENTREGA 1 (VERSIÓN BETA): GRADOS, VECINDADES Y LEMA DEL APRETÓN DE MANOS",
            "==========================================================================",
            f"• Orden del grafo: n = |V| = {n} vértices",
            f"• Tamaño del grafo: m = |A| = {m} aristas/arcos",
            "• Clasificación (Unidad 3.2):",
            "  - Simple (sin lazos ni aristas múltiples; 1-grafo).",
            "  - Dirigido (digrafo donde (u,v) indica escorrentía de u hacia v).",
            "",
            "TABLA DE GRADOS Y VECINDADES (Prof. Yesneri Zuleta & MSc Iván Gómez):",
            "--------------------------------------------------------------------------",
            f"{'Vértice':<8} {'grad⁻(v)':>8} {'grad⁺(v)':>8} {'grad(v)':>8}   {'N_G⁻(v)':<12} {'N_G⁺(v)':<12} {'N_G(v)'}",
            "--------------------------------------------------------------------------",
        ]
        for v in vs:
            lineas.append(
                f"{v:<8} {g.grad_entrada(v):>8} {g.grad_salida(v):>8} {g.grad(v):>8}   "
                f"{str(g.vecindad_entrada(v)):<12} {str(g.vecindad_salida(v)):<12} {g.vecindad_abierta(v)}"
            )
        lineas.extend([
            "--------------------------------------------------------------------------",
            f"SUMA     {sum(g_in):>8} {sum(g_out):>8} {sum(grados):>8}",
            "",
            "VALORES EXTREMOS DE GRADO (Prof. Yesneri Zuleta, diap. 8-9):",
            f"  • En grafo subyacente no dirigido: δ(G) = {min(grados)},  Δ(G) = {max(grados)}",
            f"  • En el digrafo: δ⁻(G) = {min(g_in)}, Δ⁻(G) = {max(g_in)}, δ⁺(G) = {min(g_out)}, Δ⁺(G) = {max(g_out)}",
            "",
            "VERIFICACIÓN DEL TEOREMA DEL APRETÓN DE MANOS (TAM) Y COROLARIO:",
            f"  1) En digrafo: ∑ grad⁻(v) = ∑ grad⁺(v) = m  ⇒  {sum(g_in)} = {sum(g_out)} = {m}  [CUMPLE ✓]",
            f"  2) En no dirigido: ∑ grad(v) = 2m          ⇒  {sum(grados)} = 2({m}) = {2*m}  [CUMPLE ✓]",
            f"  3) Corolario: Vértices de grado impar = {impares} (Total = {len(impares)}, número par ✓)",
        ])
        self._escribir_texto(lineas)

    def _mostrar_adyacencia(self) -> None:
        g = self.grafo
        vs = g.vertices
        mat_dir = g.matriz_adyacencia(dirigido=True)
        mat_nodir = g.matriz_adyacencia(dirigido=False)

        lineas = [
            "==========================================================================",
            "REPRESENTACIONES DE GRAFOS: LISTA Y MATRIZ DE ADYACENCIA (SECCIÓN 3.3)",
            "==========================================================================",
            "1. LISTA DE ADYACENCIA — Espacio O(|V| + |E|):",
        ]
        for v in vs:
            lineas.append(
                f"   {v} -> Salida N⁺: {g.vecindad_salida(v)}  |  Vecinos N(v): {g.vecindad_abierta(v)}"
            )
        lineas.append("")
        lineas.append("2. MATRIZ DE ADYACENCIA DIRIGIDA A (A_ij = 1 si (v_i, v_j) ∈ A):")
        lineas.append("     " + " ".join(f"{v:>3}" for v in vs))
        for i, u in enumerate(vs):
            lineas.append(f" {u:>2}  " + " ".join(f"{mat_dir[i][j]:>3}" for j in range(len(vs))))

        lineas.append("")
        lineas.append("3. MATRIZ DE ADYACENCIA NO DIRIGIDA (SIMÉTRICA: A_ij = A_ji):")
        lineas.append("     " + " ".join(f"{v:>3}" for v in vs) + "  | Suma fila = deg(v)")
        for i, u in enumerate(vs):
            lineas.append(
                f" {u:>2}  "
                + " ".join(f"{mat_nodir[i][j]:>3}" for j in range(len(vs)))
                + f"  | {sum(mat_nodir[i]):>3}"
            )
        self._escribir_texto(lineas)

    def _mostrar_incidencia(self) -> None:
        g = self.grafo
        vs = g.vertices
        arcos = g.arcos
        mat_m = g.matriz_incidencia_no_dirigida()
        etq_e = [f"e{j+1}" for j in range(len(arcos))]

        lineas = [
            "==========================================================================",
            "MATRIZ DE INCIDENCIA M (|V| × |E|) – SECCIÓN 3.3 (DIAPOSITIVA 15)",
            "==========================================================================",
            "Definición: M_ie = 1 si el vértice v_i es extremo de la arista e, y 0 en otro caso.",
            "Aristas: " + ", ".join(f"e{j+1}={u}{v}" for j, (u, v) in enumerate(arcos)),
            "",
            "     " + " ".join(f"{e:>3}" for e in etq_e) + "  | Suma fila = deg(v)",
            "   --" + "----" * len(etq_e) + "--+-------------------",
        ]
        for i, v in enumerate(vs):
            lineas.append(
                f" {v:>2}  "
                + " ".join(f"{mat_m[i][j]:>3}" for j in range(len(arcos)))
                + f"  | {sum(mat_m[i]):>3}"
            )
        col_sum = [sum(mat_m[i][j] for i in range(len(vs))) for j in range(len(arcos))]
        lineas.append("   --" + "----" * len(etq_e) + "--+-------------------")
        lineas.append("Col: " + " ".join(f"{s:>3}" for s in col_sum) + "  (Cada columna suma 2 ✓)")
        self._escribir_texto(lineas)


